package com.oyuki.marketsquare.entity; import com.oyuki.order.entity.Order; import com.oyuki.user.entity.User; import com.oyuki.marketsquare.enums.ProcurementStatus; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; import java.time.LocalDateTime; @Entity @Table(name="procurement_requests") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class ProcurementRequest { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(optional=false) @JoinColumn(name="order_id") private Order order; @ManyToOne(optional=false) @JoinColumn(name="market_id") private Market market; @ManyToOne @JoinColumn(name="agent_id") private User agent; @Enumerated(EnumType.STRING) @Builder.Default private ProcurementStatus status=ProcurementStatus.PENDING_ASSIGNMENT; private BigDecimal maximumApprovedPurchase; private LocalDateTime deliveryDeadline; private LocalDateTime acceptedAt; private LocalDateTime purchasedAt; private LocalDateTime qualityVerifiedAt; private LocalDateTime handedOverAt; @Column(nullable=false,updatable=false) private LocalDateTime createdAt; @PrePersist void pre(){if(createdAt==null)createdAt=LocalDateTime.now();} }